function admin_kce_public_url(?string $url): ?string {
    $url = trim((string)$url);
    if ($url === '') return null;
    if (filter_var($url, FILTER_VALIDATE_URL)) return $url;
    $path = '/'.ltrim($url, '/');
    $env = function_exists('kce_env') ? kce_env() : [];
    $configured = (string)($env['KCE_APP_URL'] ?? '');
    $parts = parse_url($configured);
    if (!empty($parts['scheme']) && !empty($parts['host'])) {
        return $parts['scheme'].'://'.$parts['host'].(isset($parts['port']) ? ':'.$parts['port'] : '').$path;
    }
    $domain = preg_replace('/[^A-Za-z0-9.:-]/', '', (string)($env['DOMAIN_NAME'] ?? 'kumpulblogger.com'));
    return 'https://'.$domain.$path;
}
