  }elseif($action==='status'){
   $id=(int)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,['active','paused','ended','rejected'],true))throw new RuntimeException('Status tidak valid.');
   if($status==='active'){$s=$db->prepare('SELECT COALESCE(w.balance,0),COALESCE(c.impression_unit_cost,?) FROM kce_sponsored_content c LEFT JOIN kce_advertiser_wallets w ON w.advertiser_id=c.advertiser_id WHERE c.id=?');$defaultRate=(float)kce_setting($db,'impression_article_cost','0');$s->bind_param('di',$defaultRate,$id);$s->execute();$funding=$s->get_result()->fetch_row();$s->close();if(!$funding||(float)$funding[0]<(float)$funding[1])throw new RuntimeException('Campaign tidak dapat diaktifkan: saldo advertiser tidak cukup untuk satu impression.');}
