<div class="card metric" id="performance"><div class="card-body"><h5>Materi & performa</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Materi</th><th>Status</th><th>Embedding</th><th>Impression</th><th>Click</th><th>Tarif</th><th>Biaya aktual / estimasi</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=htmlspecialchars($r['title'])?></strong><br><small class="text-muted">Advertiser #<?=(int)$r['advertiser_id']?></small></td><td><span class="status-badge status-<?=htmlspecialchars($r['status'])?>"><?=htmlspecialchars($r['status'])?></span></td><td><?=empty($r['embedding'])?'Belum':'2048 dimensi'?></td><td><?=(int)$r['impressions']?></td><td><?=(int)$r['clicks']?></td><?php $rowImpRate=$r['impression_unit_cost']!==null?(float)$r['impression_unit_cost']:(float)($settings['impression_article_cost']??0);$rowClickRate=$r['click_unit_cost']!==null?(float)$r['click_unit_cost']:(float)($settings['sponsored_click_cost']??0);$estimated=((int)$r['max_impressions']*$rowImpRate)+((int)$r['max_clicks']*$rowClickRate);?><td><small>Imp: Rp <?=number_format($rowImpRate,0,',','.')?><br>Click: Rp <?=number_format($rowClickRate,0,',','.')?></small></td><td><strong>Rp <?=number_format((float)$r['spend'],0,',','.')?></strong><br><small class="text-muted">Estimasi maks. Rp <?=number_format($estimated,0,',','.')?></small></td><td><a class="btn btn-sm btn-outline-secondary" href="?edit=<?=(int)$r['id']?>">Edit</a><form class="d-inline" method="post"><?=admin_csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="status" value="<?=$r['status']==='active'?'paused':'active'?>"><button class="btn btn-sm btn-outline-warning"><?=$r['status']==='active'?'Pause':'Aktifkan'?></button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted">Belum ada sponsored content.</td></tr><?php endif;?></tbody></table></div></div></div></main><script>
(function(){var imp=document.querySelector('[name="max_impressions"]'),click=document.querySelector('[name="max_clicks"]'),impRate=document.getElementById('impressionUnitCost'),clickRate=document.getElementById('clickUnitCost'),out=document.getElementById('estimatedBudget');function calculate(){if(!out)return;var total=(Number(imp&&imp.value)||0)*(Number(impRate&&impRate.value)||0)+(Number(click&&click.value)||0)*(Number(clickRate&&clickRate.value)||0);out.textContent='Rp '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(total)}[imp,click,impRate,clickRate].forEach(function(el){if(el)el.addEventListener('input',calculate)});calculate()})();
